export function isReservedSlug(slug: string): boolean {
  return RESERVED_SLUGS.includes(slug)
}

/** The registry's cache policy for an engine page, or null for any other page. */
export function defaultCachePolicy(id: PageId): CachePolicy | null {
  return PAGES.find((p) => p.id === id)?.cache ?? null
}

/** Finds the registry page a pathname belongs to. See matchRoute for the rules. */
export function matchPath(pathname: string): PathMatch<PageId> | null {
  return matchRoute(PAGES, RESERVED_SLUGS, pathname) as PathMatch<PageId> | null
}

// ─── match ──────────────────────────────────────────────────────────────

// Path matching for the page registry. This file has no imports: its text is
// copied into the generated registry module, so the matcher the toolkit
// tests is the one every consumer runs.

export interface RoutePage {
  id: string
  /** Null for a page no path reaches, such as not-found. */
  path: string | null
  /** True when the page also owns every path below its own. */
  prefix: boolean
}

export interface PathMatch<Id extends string = string> {
  id: Id
  /** Raw path segments by parameter name, not percent-decoded. */
  params: Record<string, string>
}

/**
 * Finds the page a pathname belongs to.
 *
 * - The pathname must start with "/". One trailing "/" is ignored; an empty
 *   segment anywhere else ("//") matches nothing.
 * - A pathname with any segment starting with "_" matches nothing. Those
 *   paths belong to the platform.
 * - A `{param}` in first position never captures a reserved slug.
 * - A prefix page matches its own path and every path below it, on a "/"
 *   boundary: /order matches /order and /order/x but not /orders.
 * - When several pages match, the one whose earliest differing segment is
 *   static wins; then the longer pattern; then an exact page over a prefix
 *   page; then registry order.
 */
export function matchRoute(
  pages: readonly RoutePage[],
  reservedSlugs: readonly string[],
  pathname: string,
): PathMatch | null {
  if (!pathname.startsWith('/')) return null
  const trimmed = pathname.length > 1 && pathname.endsWith('/') ? pathname.slice(0, -1) : pathname
  const segments = trimmed === '/' ? [] : trimmed.slice(1).split('/')
  if (segments.some((s) => s === '' || s.startsWith('_'))) return null

  let best: { match: PathMatch; rank: number[]; prefix: boolean } | null = null

  for (const page of pages) {
    if (page.path === null) continue
    const pattern = page.path === '/' ? [] : page.path.slice(1).split('/')
    if (page.prefix ? segments.length < pattern.length : segments.length !== pattern.length) continue

    const params: Record<string, string> = {}
    const rank: number[] = []
    let matched = true
    for (let i = 0; i < pattern.length; i++) {
      const part = pattern[i]!
      const segment = segments[i]!
      if (part.startsWith('{')) {
        if (i === 0 && reservedSlugs.includes(segment)) {
          matched = false
          break
        }
        params[part.slice(1, -1)] = segment
        rank.push(1)
      } else if (part === segment) {
        rank.push(0)
      } else {
        matched = false
        break
      }
    }
    if (!matched) continue

    if (best === null || outranks(rank, page.prefix, best.rank, best.prefix)) {
      best = { match: { id: page.id, params }, rank, prefix: page.prefix }
    }
  }

  return best?.match ?? null
}

function outranks(rank: number[], prefix: boolean, other: number[], otherPrefix: boolean): boolean {
  const shared = Math.min(rank.length, other.length)
  for (let i = 0; i < shared; i++) {
    if (rank[i] !== other[i]) return rank[i]! < other[i]!
  }
  if (rank.length !== other.length) return rank.length > other.length
  return !prefix && otherPrefix
}

// ─── settings ───────────────────────────────────────────────────────────

/**
 * Template settings: the values a store edits for the template it runs.
 *
 * A template declares its settings in template.json. The platform stores a
 * value per store under each setting id, and a page receives them in the
 * envelope's `settings`. When a store switches template, values whose id and
 * type both match carry over.
 *
 * The standard settings below are the well-known ids every store has. The
 * built-in default template declares exactly this set, and contract "1"
 * payloads rebuild their `content` from them.
 */

export const SETTING_TYPES = [
  'text',
  'textarea',
  'url',
  'link',
  'color',
  'boolean',
  'number',
  'select',
  'image',
  'list',
  'object-list',
] as const

export type SettingType = (typeof SETTING_TYPES)[number]

/** The types a `list` holds, and the types an `object-list` field may have. */
export const SETTING_SCALAR_TYPES = ['text', 'textarea', 'url', 'color', 'image', 'boolean', 'number'] as const

export type SettingScalarType = (typeof SETTING_SCALAR_TYPES)[number]

export interface SettingLink {
  label: string
  href: string
}

export type SettingValue =
  | string
  | number
  | boolean
  | SettingLink
  | string[]
  | Array<Record<string, string | number | boolean>>

export interface SettingOption {
  value: string
  label: string
}

/**
 * One field of each entry of an object-list setting. A field takes the same
 * optional keys as a top-level setting of its type.
 */
export interface SettingField {
  id: string
  type: SettingScalarType
  label?: string
  /** Help text shown beside the field in the editor. */
  description?: string
  /** Characters for text types; the largest value for numbers. */
  max?: number
  /** The smallest value, for numbers. */
  min?: number
  /** The increment a number moves in, counted from `min` (or zero). */
  step?: number
}

export interface SettingSchemaEntry {
  /** Lowercase words joined by dots, such as `hero.title`. */
  id: string
  type: SettingType
  label?: string
  /** Help text shown beside the setting in the editor. */
  description?: string
  /**
   * Characters for text types; for a link, the characters of its label (and
   * of its href too when `href_max` is absent); entries for lists; the
   * largest value for numbers.
   */
  max?: number
  /** Characters of a link's href. Without it, `max` limits the href as well. */
  href_max?: number
  /** The smallest value, for numbers. */
  min?: number
  /** The increment a number moves in, counted from `min` (or zero). */
  step?: number
  /** What a `list` holds. */
  of?: SettingScalarType
  /** Characters of each text item of a `list`. */
  item_max?: number
  /** The fields of each `object-list` entry. */
  fields?: SettingField[]
  /** The choices of a `select`. */
  options?: SettingOption[]
  /** What a store that has not set the value gets. */
  default?: SettingValue
}

export const SETTING_ID_PATTERN = '^[a-z][a-z0-9_-]*(\\.[a-z][a-z0-9_-]*)*$'
export const SETTING_FIELD_ID_PATTERN = '^[a-z][a-z0-9_]*$'
/** A colour is `#rgb` or `#rrggbb`. */
const HEX_COLOR = /^#(?:[0-9a-fA-F]{3}|[0-9a-fA-F]{6})$/

